import type { Dataset } from "./data/dataset.js";
import { crunch, type Buff, type BuffSource, type EngineContext, type RecipientSnapshot, type WeaponKeywordRef } from "./cruncher/index.js";
import { effectToBuffs, type ActivatableBuff, type EffectTranslation } from "./cruncher/from-dsl.js";
import { conditionFactKey } from "./cruncher/condition-facts.js";

/** The keys of every need a translation reports, in order. */
export function needKeys(result: EffectTranslation): string[] {
  return result.unsupported.flatMap((item) => (item.needs ?? []).map((need) => need.key));
}
import type { Trigger, UnitSelector } from "./generated.js";

export const RECIPIENT_CASE_PREFIX = "canonical/recipient-snapshot/";
export const HALF_WEAPON_RANGE_CASE_PREFIX = "canonical/half-weapon-range/";
export const NEGATED_CONJUNCTION_CASE_PREFIX = "canonical/negated-conjunction/";
export const TARGET_DEBUFF_CASE_PREFIX = "canonical/target-debuff/";
export const SCENARIO_CASE_PREFIX = "canonical/scenario/";
export const TRIGGER_SUBJECT_CASE_PREFIX = "canonical/trigger-subject/";
export const STRATAGEM_MODEL_CASE_PREFIX = "canonical/stratagem-model/";
export const STRATAGEM_TARGET_CASE_PREFIX = "canonical/stratagem-target/";
export const NAMED_REGION_BENEFICIARY_CASE_PREFIX = "canonical/named-region-beneficiary/";
export const DESIGNATION_CASE_PREFIX = "canonical/designation/";
export const MOVE_TYPE_CASE_PREFIX = "canonical/move-type/";
export const REMOVED_KEYWORD_CASE_PREFIX = "canonical/removed-keyword/";

export interface DslInput {
  caseId: string;
  abilityId: string;
  effect: unknown;
  source: Extract<BuffSource, { kind: "ability" }>;
  context: EngineContext;
  perspective: "attacker" | "target";
}

/** Fabricated, source-attested history; deliberately no current attachment-role evidence. */
export function canonicalRecipientCases() {
  const source = { kind: "ability", abilityId: "snapshot-example", abilityKind: "attached", sourceUnitId: "source" } as const;
  const trigger: Trigger = { event: "battle-started", condition: { type: "attachment", parameters: { subject: "this-model", role: "leading" } } };
  const selector: UnitSelector = { filter: { level: "model", member_of: "this-unit", attachment_role: "bodyguard" } };
  const pool = { type: "for-each-unit", selector, effect: { type: "sequence", steps: [
    { type: "stat-modifier", target: "recipient", modifier: { stat: "S", operation: "add", value: 1, weapons: { type: "melee" } } },
    { type: "stat-modifier", target: "recipient", modifier: { stat: "T", operation: "add", value: 1 } },
  ] } };
  // from-dsl consumes an effect, not an ability record. A real local part trigger carries
  // the same activation without pre-resolving the historical recipient in the generator.
  const effect = { type: "ability-part", trigger, duration: "battle", effect: pool };
  const snapshot: RecipientSnapshot = { source, sourceUnitId: "source", trigger, selector, selectionPath: "/effect", perspective: "attacker", recipientUnitId: "recipient", selected: true };
  const context: EngineContext = { phase: "fight", attackerUnitId: "recipient", attackerKeywords: ["INFANTRY", "CHARACTER"], attackerAttached: false };
  const cases: DslInput[] = [];
  const add = (id: string, snapshots: RecipientSnapshot[], overrides: Partial<DslInput> = {}) => {
    cases.push({ caseId: `${RECIPIENT_CASE_PREFIX}${id}`, abilityId: source.abilityId, source, effect,
      context: { ...context, recipientSnapshots: snapshots }, perspective: "attacker", ...overrides });
  };
  add("attested-strength-after-detachment", [snapshot]);
  add("attested-toughness-after-detachment", [], {
    perspective: "target",
    context: { phase: "fight", targetUnitId: "recipient", targetKeywords: ["INFANTRY", "CHARACTER"], targetAttached: false, recipientSnapshots: [{ ...snapshot, perspective: "target" }] },
  });
  add("missing", []);
  // A loop that only marks units grants nothing, so it needs no snapshot and leaves the rest of the part scored.
  const marking = { type: "for-each-unit", selector: { filter: { owner: "friendly" } }, effect: { type: "designate", target: "recipient", modifier: { tag: "example-mark" } } };
  add("mark-only-loop-needs-none", [], { effect: { ...effect, effect: { type: "sequence", steps: [marking,
    { type: "stat-modifier", target: "this-unit", modifier: { stat: "S", operation: "add", value: 1, weapons: { type: "melee" } } }] } } });
  add("wrong-source-unit", [{ ...snapshot, sourceUnitId: "outsider" }]);
  add("wrong-source-identity", [{ ...snapshot, source: { ...source, sourceUnitId: "outsider" } }]);
  add("conflicting", [snapshot, { ...snapshot, selected: false }]);
  add("known-nonrecipient", [{ ...snapshot, selected: false }]);
  add("wrong-recipient", [{ ...snapshot, recipientUnitId: "source" }]);
  add("wrong-perspective", [{ ...snapshot, perspective: "target" }]);
  add("wrong-trigger", [{ ...snapshot, trigger: { event: "turn-started" } }]);
  add("wrong-selection-path", [{ ...snapshot, selectionPath: "" }]);
  add("wrong-selector-role", [{ ...snapshot, selector: { filter: { ...selector.filter, attachment_role: "leader" } } }]);
  add("reordered-object-fields", [{ ...snapshot, selector: { filter: { attachment_role: "bodyguard", member_of: "this-unit", level: "model" } }, trigger: { condition: trigger.condition, event: "battle-started" } }]);
  add("nested-local-trigger-path", [{ ...snapshot, selectionPath: "/steps/0/effect" }], { effect: { type: "sequence", steps: [effect] } });
  add("recipient-relative-ap-ws-bs", [snapshot], { effect: { ...effect, effect: { ...pool, effect: { type: "sequence", steps: ["AP", "WS", "BS"].map((stat) => ({
    type: "stat-modifier", target: "recipient", modifier: { stat, operation: "improve", value: 1 },
  })) } } } });
  // A named menu option is its own lever: only the option whose pool is unresolved is refused.
  const hit = { type: "roll-modifier", target: "this-unit", modifier: { roll: "hit", operation: "add", value: 1 } };
  const menu = (type: string) => ({ type, mode: "consumable", options: [{ id: "keen", name: "Keen", effect: hit }, { id: "rally", name: "Rally", effect }] });
  add("stance-option-missing", [], { effect: menu("stance-select") });
  add("stance-option-attested", [{ ...snapshot, selectionPath: "/options/1/effect/effect" }], { effect: menu("stance-select") });
  add("orders-option-missing", [], { effect: menu("issue-orders") });
  add("choice-composition-refused", [], { effect: { type: "choice", options: [hit, effect] } });
  return cases.map((row) => {
    const result = effectToBuffs(row.effect, row.source, row.context, row.perspective);
    return { ...row, expected: dslProjection(result) };
  });
}

/**
 * Fabricated moments with no `subject`: a unit's own moment (selected to shoot) is the ability's own
 * unit's, so `event-subject` binds to it; a clock moment (start of phase) names no unit and stays unbound.
 */
export function canonicalTriggerSubjectCases() {
  const source = { kind: "ability", abilityId: "trigger-subject-example", abilityKind: "unit" } as const;
  const grant = { type: "weapon-ability-grant", target: "event-subject", modifier: { keywords: [{ keyword_id: "sustained-hits", parameters: { value: 1 } }] } };
  const holderGated = (abilityId: string) => ({ type: "conditional", condition: { type: "matches", parameters: { subject: "event-subject", filter: { has_ability: [abilityId] } } }, effect: grant });
  const cases: DslInput[] = [
    { caseId: `${TRIGGER_SUBJECT_CASE_PREFIX}owned-moment-defaults-to-this-unit`, effect: { type: "ability-part", trigger: { event: "selected", filter: { to: "shoot" } }, effect: grant } },
    { caseId: `${TRIGGER_SUBJECT_CASE_PREFIX}clock-moment-stays-unbound`, effect: { type: "ability-part", trigger: { event: "phase-started", condition: { type: "phase-is", parameters: { phase: "shooting" } } }, effect: grant } },
    // "Each time a unit with this ability is selected to shoot": the holder has the ability it resolves.
    { caseId: `${TRIGGER_SUBJECT_CASE_PREFIX}condition-subject-holds-own-ability`, effect: { type: "ability-part", trigger: { event: "selected", filter: { to: "shoot" } }, effect: holderGated(source.abilityId) } },
    { caseId: `${TRIGGER_SUBJECT_CASE_PREFIX}condition-subject-other-ability-unknown`, effect: { type: "ability-part", trigger: { event: "selected", filter: { to: "shoot" } }, effect: holderGated("another-ability") } },
  ].map((row) => ({ ...row, abilityId: source.abilityId, source, context: { phase: "shooting" }, perspective: "attacker" as const }));
  // "When a friendly PALADIN SQUAD unit is selected to fight": only in the Fight phase, and only for a unit with those keywords.
  const fightSelection = (subject?: Record<string, unknown>) => ({ type: "ability-part", trigger: { event: "selected", filter: { to: "fight" }, ...(subject ? { subject } : {}) }, effect: grant });
  const paladins = { owner: "friendly", all_of: ["PALADIN SQUAD"] };
  const selection: Array<{ id: string; effect: unknown; context: EngineContext }> = [
    { id: "selected-to-fight-outside-fight", effect: fightSelection(), context: { phase: "shooting" } },
    { id: "selected-to-fight-in-fight", effect: fightSelection(), context: { phase: "fight" } },
    { id: "subject-keywords-held", effect: fightSelection(paladins), context: { phase: "fight", attackerKeywords: ["Infantry", "Paladin Squad"] } },
    { id: "subject-keywords-missing", effect: fightSelection(paladins), context: { phase: "fight", attackerKeywords: ["Vehicle", "Titanic"] } },
  ];
  cases.push(...selection.map(({ id, ...row }) => ({ caseId: `${TRIGGER_SUBJECT_CASE_PREFIX}${id}`, ...row, abilityId: source.abilityId, source, perspective: "attacker" as const })));
  return cases.map((row) => {
    const result = effectToBuffs(row.effect, row.source, row.context, row.perspective);
    return { ...row, expected: dslProjection(result) };
  });
}

/**
 * Fabricated Stratagem effects on `this-model`. A Stratagem that targets one model (`selectsModel`)
 * buffs the unit only when the unit is that one model; a multi-model or uncounted unit gets nothing.
 */
export function canonicalStratagemModelCases() {
  const selecting = { kind: "ability", abilityId: "stratagem-model-example", abilityKind: "detachment-stratagem", selectsModel: true } as const;
  const unitWide = { kind: "ability", abilityId: "stratagem-model-example", abilityKind: "detachment-stratagem" } as const;
  const attacks = { type: "stat-modifier", target: "this-model", modifier: { stat: "A", operation: "add", value: 1, weapons: { type: "melee" } } };
  const toughness = { type: "stat-modifier", target: "this-model", modifier: { stat: "T", operation: "add", value: 1 } };
  const rows: Array<Omit<DslInput, "abilityId" | "caseId"> & { id: string }> = [
    { id: "multi-model-unit", source: selecting, effect: attacks, context: { phase: "fight", attackerModelCount: 6 }, perspective: "attacker" },
    { id: "uncounted-unit", source: selecting, effect: attacks, context: { phase: "fight" }, perspective: "attacker" },
    { id: "one-model-unit", source: selecting, effect: attacks, context: { phase: "fight", attackerModelCount: 1 }, perspective: "attacker" },
    { id: "unit-target-stratagem", source: unitWide, effect: attacks, context: { phase: "fight", attackerModelCount: 6 }, perspective: "attacker" },
    { id: "multi-model-defender", source: selecting, effect: toughness, context: { phase: "shooting", targetModelCount: 6 }, perspective: "target" },
  ];
  return rows.map(({ id, ...row }) => {
    const result = effectToBuffs(row.effect, row.source, row.context, row.perspective);
    return { caseId: `${STRATAGEM_MODEL_CASE_PREFIX}${id}`, abilityId: row.source.abilityId, ...row, expected: dslProjection(result) };
  });
}

/**
 * A fabricated two-target Stratagem whose effect names each target: the context says which named
 * friendly targets the crunched unit is, and a name it does not list stays unresolved.
 */
export function canonicalStratagemTargetCases() {
  const source = { kind: "ability", abilityId: "stratagem-target-example", abilityKind: "detachment-stratagem" } as const;
  const fnp = (name: string, threshold: number) => ({ type: "feel-no-pain", target: { stratagem_target: name }, modifier: { threshold } });
  const effect = { type: "sequence", steps: [fnp("first", 5), fnp("second", 4)] };
  const rows: Array<Omit<DslInput, "abilityId" | "caseId"> & { id: string }> = [
    { id: "unit-is-first-only", source, effect, context: { phase: "shooting", stratagemTargets: { first: true, second: false } }, perspective: "target" },
    { id: "unit-is-both", source, effect, context: { phase: "shooting", stratagemTargets: { first: true, second: true } }, perspective: "target" },
    { id: "targets-unknown", source, effect, context: { phase: "shooting" }, perspective: "target" },
    { id: "unlisted-name", source, effect: fnp("third", 5), context: { phase: "shooting", stratagemTargets: { first: true } }, perspective: "target" },
  ];
  return rows.map(({ id, ...row }) => {
    const result = effectToBuffs(row.effect, row.source, row.context, row.perspective);
    return { caseId: `${STRATAGEM_TARGET_CASE_PREFIX}${id}`, abilityId: row.source.abilityId, ...row, expected: dslProjection(result) };
  });
}

/**
 * A fabricated named region whose beneficiary filter is read as a unit filter against the
 * attacker's facts: keyword lists, a model-level filter, and a filter with no facts to read.
 */
export function canonicalNamedRegionBeneficiaryCases() {
  const source = { kind: "ability", abilityId: "named-region-example", abilityKind: "army" } as const;
  const region = { region_id: "example-region", owner_faction: "example-faction" };
  const effect = (filter: Record<string, unknown>) => ({
    type: "named-region-state",
    target: { owner: "friendly" },
    modifier: {
      region_ref: region,
      consumer: {
        state_ref: region,
        beneficiary_filter: { owner: "friendly", ...filter },
        membership: { unit_scope: "whole-unit", relation: "wholly-within" },
        qualified_condition: { type: "matches", parameters: { filter: { all_of: ["EXAMPLE"] } } },
        default_branch: { effect: { type: "re-roll", target: "this-unit", modifier: { roll: "hit", subset: "ones" } } },
        qualified_branch: { effect: { type: "re-roll", target: "this-unit", modifier: { roll: "hit", subset: "all-failures" } } },
      },
    },
  });
  const context = { phase: "shooting" as const, attackerKeywords: ["infantry", "example"] };
  const rows: Array<Omit<DslInput, "abilityId" | "caseId"> & { id: string }> = [
    { id: "any-of-held", source, effect: effect({ any_of: ["VEHICLE", "INFANTRY"] }), context, perspective: "attacker" },
    { id: "none-of-held", source, effect: effect({ none_of: ["VEHICLE", "INFANTRY"] }), context, perspective: "attacker" },
    { id: "none-of-clear", source, effect: effect({ none_of: ["VEHICLE"] }), context, perspective: "attacker" },
    { id: "not-all-of-held", source, effect: effect({ not_all_of: ["INFANTRY", "EXAMPLE"] }), context, perspective: "attacker" },
    { id: "model-level-unknown", source, effect: effect({ level: "model", all_of: ["EXAMPLE"] }), context, perspective: "attacker" },
    { id: "model-level-every-model", source, effect: effect({ level: "model", all_of: ["EXAMPLE"] }), context: { ...context, attackerModelKeywords: ["infantry", "example"] }, perspective: "attacker" },
    { id: "no-keywords", source, effect: effect({ any_of: ["INFANTRY"] }), context: { phase: "shooting" as const }, perspective: "attacker" },
  ];
  return rows.map(({ id, ...row }) => {
    const result = effectToBuffs(row.effect, row.source, row.context, row.perspective);
    return { caseId: `${NAMED_REGION_BENEFICIARY_CASE_PREFIX}${id}`, abilityId: row.source.abilityId, ...row, expected: dslProjection(result) };
  });
}

/**
 * A fabricated designation with one entry on the designated unit and one on attacks against it: the
 * attacks' entry is the lever, the unit's own entry is reported unsupported, whatever the entry order.
 */
export function canonicalDesignationCases() {
  const source = { kind: "ability", abilityId: "designation-example", abilityKind: "unit" } as const;
  const cover = { to: "target", effect: { type: "rule-state", target: "selected-unit", modifier: { direction: "suppressed", rule_kind: "core-rule", rule: "benefit-of-cover" } } };
  const strength = { to: "attackers-of-target", effect: { type: "stat-modifier", target: { owner: "friendly" }, modifier: { stat: "S", operation: "improve", value: 2 } } };
  const designation = (applies: unknown[]) => ({ type: "designate-target", designation: "combined-fire-target", select: { kind: "unit", selector: { filter: { owner: "enemy" }, count: { min: 1, max: 1 } } }, applies, duration: "phase" });
  const rows: Array<Omit<DslInput, "abilityId" | "caseId"> & { id: string }> = [
    { id: "applies-list-unit-first", source, effect: designation([cover, strength]), context: { phase: "shooting" as const }, perspective: "attacker" },
    { id: "applies-list-attacks-first", source, effect: designation([strength, cover]), context: { phase: "shooting" as const }, perspective: "attacker" },
  ];
  return rows.map(({ id, ...row }) => {
    const result = effectToBuffs(row.effect, row.source, row.context, row.perspective);
    return { caseId: `${DESIGNATION_CASE_PREFIX}${id}`, abilityId: row.source.abilityId, ...row, expected: dslProjection(result) };
  });
}

/**
 * Fabricated move types: what follows a move is a lever vouched for by that move (a disembark mode's
 * lever names its mode), a move type with nothing after it offers nothing, and a non-buff after
 * (a charge ban) is reported unsupported rather than applied.
 */
export function canonicalMoveTypeCases() {
  const source = { kind: "ability", abilityId: "move-type-example", abilityKind: "army" } as const;
  const penalty = { type: "ability-part", duration: "until-start-next-turn", effect: { type: "roll-modifier", target: "this-unit", modifier: { roll: "hit", operation: "subtract", value: 1, incoming: true } } };
  const noCharge = { type: "ability-part", duration: "turn", effect: { type: "permission", target: "this-unit", modifier: { activity: "declare-charge", allow: false } } };
  const jet = { type: "move-type", name: "Example Jet Move", move_type: "pulse-jet", distance: "D6+18", after: { type: "sequence", steps: [noCharge, penalty] } };
  const drop = { type: "move-type", name: "Example Drop Move", move_type: "disembark", mode: "assault", setup_distance: { inches: 3 }, after: penalty };
  const bare = { type: "move-type", name: "Example Bare Move", move_type: "disembark", mode: "shock", setup_distance: { inches: 3 } };
  const rows: Array<Omit<DslInput, "abilityId" | "caseId"> & { id: string }> = [
    { id: "after-lever-defending", source, effect: jet, context: { phase: "shooting" as const }, perspective: "target" },
    { id: "after-lever-mode", source, effect: drop, context: { phase: "shooting" as const }, perspective: "target" },
    { id: "nothing-after", source, effect: bare, context: { phase: "shooting" as const }, perspective: "target" },
    { id: "after-lever-attacking", source, effect: jet, context: { phase: "shooting" as const }, perspective: "attacker" },
  ];
  return rows.map(({ id, ...row }) => {
    const result = effectToBuffs(row.effect, row.source, row.context, row.perspective);
    return { caseId: `${MOVE_TYPE_CASE_PREFIX}${id}`, abilityId: row.source.abilityId, ...row, expected: dslProjection(result) };
  });
}

/** A fabricated weapon-ability removal: "this unit's ranged weapons do not have [Blast]". */
function removal(weapons: unknown, removes: unknown[] = [{ keyword_id: "blast" }]) {
  return { type: "weapon-ability-grant", target: "this-unit", modifier: { keywords: [], removes, weapons } };
}

/**
 * Fabricated weapon-ability removals: each valid reference is a `removed-keyword` buff gated like a
 * grant, an invalid reference or a weapon ref the cruncher cannot resolve is reported, and a lever
 * that removes a keyword is labelled "loses <keyword>".
 */
export function canonicalRemovedKeywordCases() {
  const source = { kind: "ability", abilityId: "removed-keyword-example", abilityKind: "unit" } as const;
  const lethal = { type: "weapon-ability-grant", target: "this-unit", modifier: { keywords: [{ keyword_id: "lethal-hits" }] } };
  const rows: Array<{ id: string; effect: unknown }> = [
    { id: "ranged", effect: removal({ type: "ranged" }) },
    { id: "torrent-scoped", effect: removal({ type: "ranged", keyword: { keyword_id: "torrent" } }) },
    { id: "invalid-reference", effect: removal({ type: "ranged" }, [{ keyword_id: "" }, "blast"]) },
    { id: "unresolved-weapon-ref", effect: removal({ ref: "example-weapon" }) },
    { id: "choice-label", effect: { type: "choice", options: [removal({ type: "ranged" }), lethal] } },
  ];
  return rows.map((row) => withGates(dslExpectation({
    caseId: `${REMOVED_KEYWORD_CASE_PREFIX}${row.id}`,
    abilityId: source.abilityId,
    source,
    effect: row.effect,
    context: { phase: "shooting" },
    perspective: "attacker",
  })));
}

/** A lever's stance-option gate, projected only when it has one so ungated goldens keep their shape. */
export function stanceOptionFields(lever: ActivatableBuff): Pick<ActivatableBuff, "requiresOption" | "excludesOption"> {
  return {
    ...(lever.requiresOption ? { requiresOption: lever.requiresOption } : {}),
    ...(lever.excludesOption ? { excludesOption: lever.excludesOption } : {}),
  };
}

/** Fabricated conditional buff cases for the attacker/defender half-weapon relationship. */
export function canonicalHalfWeaponRangeCases() {
  const source = { kind: "ability", abilityId: "fabricated-half-weapon-range", abilityKind: "unit" } as const;
  const baseWithin = { range: "half-weapon", of: "attacker" };
  const buff = { type: "stat-modifier", target: "this-unit", modifier: { stat: "S", operation: "add", value: 1 } };
  const conditional = (within: unknown) => ({
    type: "conditional",
    condition: { type: "matches", parameters: { subject: "defender", filter: { owner: "enemy", level: "unit", within } } },
    effect: buff,
  });
  const inputs: Array<{ id: string; context: EngineContext; effect: unknown }> = [
    { id: "known-true", context: { phase: "shooting", withinHalfRange: true }, effect: conditional(baseWithin) },
    { id: "known-false", context: { phase: "shooting", withinHalfRange: false }, effect: conditional(baseWithin) },
    { id: "missing-unknown", context: { phase: "shooting" }, effect: conditional(baseWithin) },
    { id: "wholly-unknown", context: { phase: "shooting", withinHalfRange: true }, effect: conditional({ ...baseWithin, wholly: true }) },
    { id: "unrelated-unknown", context: { phase: "shooting", withinHalfRange: true }, effect: conditional({ ...baseWithin, of: "defender" }) },
  ];
  return inputs.map((input) => {
    const row: DslInput = {
      caseId: `${HALF_WEAPON_RANGE_CASE_PREFIX}${input.id}`,
      abilityId: source.abilityId,
      source,
      effect: input.effect,
      context: input.context,
      perspective: "attacker",
    };
    const result = effectToBuffs(row.effect, row.source, row.context, row.perspective);
    return { ...row, expected: dslProjection(result) };
  });
}

/**
 * A negated conjunction mixing unit and attack-scoped operands (Blight Bombardment's "ranged, and not
 * (ranged and Blast)"): its unit operands are decided first, leaving the attack-scoped operand's
 * negation as the per-weapon gate, the negation holding outright, or the condition unresolved.
 */
export function canonicalNegatedConjunctionCases() {
  const source = { kind: "ability", abilityId: "fabricated-negated-conjunction", abilityKind: "unit" } as const;
  const ranged = { type: "attack-is", parameters: { attack_type: "ranged" } };
  const blast = { type: "attack-is", parameters: { weapons: { keyword: { keyword_id: "blast" } } } };
  const lateRounds = { type: "battle-round", parameters: { min: 3 } };
  const rerollOnes = (condition: unknown) => ({
    type: "conditional",
    condition,
    effect: { type: "re-roll", target: "this-unit", modifier: { roll: "hit", subset: "ones" } },
  });
  const notBoth = (left: unknown) => ({ operator: "not", operands: [{ operator: "and", operands: [left, blast] }] });
  const blightShape = { operator: "and", operands: [ranged, notBoth(ranged)] };
  const inputs: Array<{ id: string; context: EngineContext; effect: unknown }> = [
    { id: "unit-operand-true-gates-per-weapon", context: { phase: "shooting" }, effect: rerollOnes(blightShape) },
    { id: "enclosing-operand-fails", context: { phase: "fight" }, effect: rerollOnes(blightShape) },
    { id: "unit-operand-false-holds-outright", context: { phase: "fight" }, effect: rerollOnes(notBoth(ranged)) },
    { id: "unit-operand-undecided", context: { phase: "shooting" }, effect: rerollOnes(notBoth(lateRounds)) },
  ];
  return inputs.map((input) => {
    const row: DslInput = {
      caseId: `${NEGATED_CONJUNCTION_CASE_PREFIX}${input.id}`,
      abilityId: source.abilityId,
      source,
      effect: input.effect,
      context: input.context,
      perspective: "attacker",
    };
    const result = effectToBuffs(row.effect, row.source, row.context, row.perspective);
    return { ...row, expected: dslProjection(result) };
  });
}

/**
 * The attacker's rule changing the attack target's Toughness or Save (Nurgle's Gift on Afflicted
 * enemies): a target-side contribution from the attacker perspective, gated by the enemy filter.
 */
export function canonicalTargetDebuffCases() {
  const source = { kind: "ability", abilityId: "fabricated-target-debuff", abilityKind: "army" } as const;
  const afflicted = { owner: "enemy", designated: "afflicted" };
  const toughness = { type: "stat-modifier", target: afflicted, modifier: { stat: "T", operation: "subtract", value: 1 } };
  const save = { type: "stat-modifier", target: afflicted, modifier: { stat: "Sv", operation: "worsen", value: 1 } };
  const onDefender = { type: "stat-modifier", target: "defender", modifier: { stat: "T", operation: "subtract", value: 1 } };
  const inputs: Array<{ id: string; context: EngineContext; effect: unknown }> = [
    { id: "toughness-on-designated-target", context: { phase: "fight", targetDesignations: ["afflicted"] }, effect: toughness },
    { id: "save-on-designated-target", context: { phase: "fight", targetDesignations: ["afflicted"] }, effect: save },
    { id: "target-not-designated", context: { phase: "fight", targetDesignations: [] }, effect: toughness },
    { id: "designation-undecided", context: { phase: "fight" }, effect: save },
    { id: "toughness-on-defender", context: { phase: "shooting" }, effect: onDefender },
  ];
  return inputs.map((input) => {
    const row: DslInput = {
      caseId: `${TARGET_DEBUFF_CASE_PREFIX}${input.id}`,
      abilityId: source.abilityId,
      source,
      effect: input.effect,
      context: input.context,
      perspective: "attacker",
    };
    const result = effectToBuffs(row.effect, row.source, row.context, row.perspective);
    return { ...row, expected: dslProjection(result) };
  });
}

/**
 * A translation's from-dsl expectation as every port projects it: contributions, reasons, each
 * reason's scope, need keys and levers.
 */
export function dslProjection(result: EffectTranslation) {
  return {
    applied: result.applied.map((applied) => applied.contribution),
    unsupportedReasons: result.unsupported.map((item) => item.reason),
    unsupportedScopes: result.unsupported.map((item) => item.scope ?? "unresolved"),
    needKeys: needKeys(result),
    activatable: result.activatable.map((lever) => ({
      id: lever.id, label: lever.label, group: lever.group ?? null,
      requires: lever.requires ?? null, capRaise: lever.capRaise ?? null,
      ...stanceOptionFields(lever),
      // Projected only on a secondary-effect lever, so other goldens keep their shape.
      ...(lever.secondary ? { secondary: true } : {}),
      // Each buff's gate (null when ungated), projected only on a lever with a gated buff.
      ...(lever.buffs.some((applied) => applied.applicableWhen) ? { gates: lever.buffs.map((applied) => applied.applicableWhen ?? null) } : {}),
      buffs: lever.buffs.map((applied) => applied.contribution),
    })),
  };
}

/** The from-dsl row's expectation: contributions, reasons and levers, as every port projects them. */
export function dslExpectation(row: DslInput) {
  const result = effectToBuffs(row.effect, row.source, row.context, row.perspective);
  return { ...row, expected: dslProjection(result) };
}

